{
  "probability": 0.47,
  "range_low": 0.38,
  "range_high": 0.56,
  "summary": [
    "Anchored on the base-rate forecast for state-on-state chemical weapons use within 12 months (~12%).",
    "Upward updates from escalation pressure, credible warnings, and OPCW-detected CS presence increase the probability.",
    "Downward effects from strong norms/deterrence and escalation risks keep the probability below the high end.",
    "Calibrated posterior probability is 0.47 with an approximate 0.38–0.56 uncertainty band."
  ],
  "confidence": "high",
  "narrative": "Starting from a base-rate forecast around 12%, key updates from escalation dynamics, credible intelligence, and OPCW findings push the probability higher. Strong norms and deterrence, plus attribution uncertainty, temper the rise, yielding a calibrated probability of 47% with a modest uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Swift Centre median forecast for chemical/biological weapon use in the next 12 months; aligns with the base-rate reference class for interstate chemical weapons use in Ukraine timing horizon."
    },
    "factor_updates": [
      {
        "factor": "Escalation pressure in ongoing war",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher battlefield intensity raises incentives to consider chemical options as a rapid escalation tool, though norms deter actual use."
      },
      {
        "factor": "Credible intelligence warnings of increased state-use risk (Russia)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Public assessments of elevated risk lift the probability beyond the anchor."
      },
      {
        "factor": "OPCW findings of riot-control agent CS in Ukraine incidents",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Documented presence of CS increases capability/occurrence signals; attribution remains unsettled."
      },
      {
        "factor": "Robust international norms under the Chemical Weapons Convention",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Deterrence and verification mechanisms impose high costs for use, substantially dampening probability."
      },
      {
        "factor": "Attribution uncertainty and potential deniability",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Unclear attribution adds uncertainty but does not clearly tilt probability in a single direction."
      },
      {
        "factor": "Operational/logistical constraints and escalation risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Delivery challenges and fear of broader escalation reduce attractiveness of chemical options."
      }
    ],
    "synthesis_rationale": "Starting from a 12% anchor, the model incorporates several up-datings (escalation, intelligence warnings, OPCW findings) that collectively raise the probability. Downward pressures from norms, deterrence, attribution uncertainty, and escalation risk temper the rise. The factors are treated as moderately correlated; after calibration, the posterior probability converges to 0.47 with a calibrated 0.38–0.56 range."
  }
}

{
  "probability": 0.47,
  "range_low": 0.40,
  "range_high": 0.54,
  "summary": [
    "Posterior probability of any state actor using chemical weapons in Ukraine before May 1, 2026 is 47%.",
    "Upward updates from credible intelligence warnings and OPCW-detected CS incidents increase risk from the anchor.",
    "Strong international norms against WMD reduce the probability, providing downward pressure.",
    "Attribution uncertainty and escalation risks inject remaining uncertainty, yielding a modestly wide range."
  ],
  "confidence": "high",
  "narrative": "Using a 12% anchor from forecast canvases, recent intelligence warnings and OPCW findings push the probability higher, but enduring norms and attribution ambiguity cap the rise. The resulting posterior around 0.47 reflects a non-negligible but bounded risk within the horizon.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Forecast canvases (e.g., Swift Centre) cite median near-term risk around 12% for chemical/biological weapon use; serves as a conservative starting point for updates."
    },
    "factor_updates": [
      {
        "factor": "Escalation pressure in ongoing war",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Intensified fighting creates incentives to deploy chemical options as a tactical lever, nudging probability upward."
      },
      {
        "factor": "Credible intelligence warnings of increased state-use risk (Russia)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Publicized assessments of elevated risk from allied intelligence raise the baseline likelihood."
      },
      {
        "factor": "OPCW findings of riot-control agent CS presence on Ukraine frontlines",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Laboratory-confirmed presence of CS in incidents signals capability and increases near-term risk even without attribution."
      },
      {
        "factor": "Robust international norms under the Chemical Weapons Convention",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Deterrence and verification impose high costs; reduce likelihood of state use."
      },
      {
        "factor": "Attribution uncertainty and potential deniability",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Unclear attribution complicates costs and responses, injecting uncertainty rather than directional shift."
      },
      {
        "factor": "Operational/logistical constraints and escalation risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Delivery challenges and fear of broader escalation deter broad or repeat use."
      }
    ],
    "synthesis_rationale": "Starting from a modest anchor, the moderate up-deltas from escalation, credible warnings, and OPCW-detected CS incidents are weighed against a strong down-delta from norms and deterrence, plus a neutral attribution uncertainty factor and logistics risk. The combination yields a posterior near the mid-point of the prior, around 0.47, with a calibrated 95% plausible range approximately 0.40–0.54. Caveats include attribution ambiguity and evolving norms or escalation dynamics that could shift probability."
  }
}

